SELECT \* FROM character_inventory ci LEFT JOIN item_instance ii ON ci.item=ii.guid WHERE ii.guid IS NULL;
and 
DELETE ci FROM character_inventory ci LEFT JOIN item_instance ii ON ci.item=ii.guid WHERE ii.guid IS NULL;

