causes signed / unsigned mismatch in Spell::update
patch fix:

``` code
Core/Spells: Fixed signed/unsigned mismatch caused by f8a13b401d

--- a/src/server/game/Spells/Spell.cpp  Thu Dec 22 11:37:30 2011 +0100
+++ b/src/server/game/Spells/Spell.cpp  Thu Dec 22 11:54:28 2011 +0100
@@ -3522,7 +3522,7 @@
     _player->AddSpellAndCategoryCooldowns(m_spellInfo, m_CastItem ? m_CastItem->GetEntry() : 0, this);
 }

-void Spell::update(uint32 difftime)
+void Spell::update(int32 difftime)
 {
     // update pointers based at it's GUIDs
     UpdatePointers();
--- a/src/server/game/Spells/Spell.h    Thu Dec 22 11:37:30 2011 +0100
+++ b/src/server/game/Spells/Spell.h    Thu Dec 22 11:54:28 2011 +0100
@@ -366,7 +366,7 @@

         void prepare(SpellCastTargets const* targets, AuraEffect const* triggeredByAura = NULL);
         void cancel();
-        void update(uint32 difftime);
+        void update(int32 difftime);
         void cast(bool skipCheck = false);
         void finish(bool ok = true);
         void TakePower();
```

